import React from 'react';
import { Card, CardContent, Typography, Grid, Stack, Box, Chip } from '@mui/material';
import { Line, Doughnut, Bar, Radar } from 'react-chartjs-2';
import { Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, ArcElement, BarElement, RadialLinearScale, Tooltip as ChartTooltip, Legend } from 'chart.js';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, ArcElement, BarElement, RadialLinearScale, ChartTooltip, Legend);

function AnalyticsCharts() {
  const lineData = {
    labels: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun'],
    datasets: [
      { label: 'Passes', data: [82, 85, 88, 90, 91, 92], borderColor: '#2563EB', backgroundColor: 'rgba(37,99,235,0.15)', tension: 0.4, fill: true },
      { label: 'Failures', data: [18, 15, 12, 10, 9, 8], borderColor: '#EF4444', backgroundColor: 'rgba(239,68,68,0.12)', tension: 0.4, fill: true },
    ],
  };

  const donutData = {
    labels: ['Auth', 'Payments', 'Search', 'UI'],
    datasets: [{ data: [35, 25, 20, 20], backgroundColor: ['#2563EB', '#0EA5E9', '#22C55E', '#F59E0B'] }],
  };

  const barData = {
    labels: ['Login Flow', 'Checkout', 'Search', 'Billing'],
    datasets: [{ label: 'Flake Rate', data: [83, 76, 61, 54], backgroundColor: ['#EF4444', '#F59E0B', '#0EA5E9', '#22C55E'] }],
  };

  const radarData = {
    labels: ['Reliability', 'Coverage', 'Stability', 'Speed', 'Observability'],
    datasets: [{ label: 'Score', data: [88, 92, 81, 76, 90], backgroundColor: 'rgba(14,165,233,0.2)', borderColor: '#0EA5E9' }],
  };

  return (
    <Grid container spacing={3}>
      <Grid item xs={12} lg={8}>
        <Card>
          <CardContent>
            <Stack direction="row" justifyContent="space-between" alignItems="center" mb={2}>
              <Typography variant="h6">Pass vs Fail Trend</Typography>
              <Chip label="Live Signal" color="primary" />
            </Stack>
            <Line data={lineData} options={{ responsive: true, plugins: { legend: { labels: { color: '#F8FAFC' } } }, scales: { x: { ticks: { color: '#CBD5E1' }, grid: { color: 'rgba(255,255,255,0.06)' } }, y: { ticks: { color: '#CBD5E1' }, grid: { color: 'rgba(255,255,255,0.06)' } } } }} />
          </CardContent>
        </Card>
      </Grid>
      <Grid item xs={12} lg={4}>
        <Card>
          <CardContent>
            <Typography variant="h6" mb={2}>Module Failure Distribution</Typography>
            <Doughnut data={donutData} options={{ responsive: true, plugins: { legend: { position: 'bottom', labels: { color: '#F8FAFC' } } } }} />
          </CardContent>
        </Card>
      </Grid>
      <Grid item xs={12} lg={6}>
        <Card>
          <CardContent>
            <Typography variant="h6" mb={2}>Top Flaky Tests</Typography>
            <Bar data={barData} options={{ responsive: true, plugins: { legend: { display: false } }, scales: { x: { ticks: { color: '#CBD5E1' }, grid: { display: false } }, y: { ticks: { color: '#CBD5E1' }, grid: { color: 'rgba(255,255,255,0.06)' } } } }} />
          </CardContent>
        </Card>
      </Grid>
      <Grid item xs={12} lg={6}>
        <Card>
          <CardContent>
            <Typography variant="h6" mb={2}>30 Day Quality Posture</Typography>
            <Radar data={radarData} options={{ responsive: true, plugins: { legend: { display: false } }, scales: { r: { suggestedMin: 50, grid: { color: 'rgba(255,255,255,0.08)' }, angleLines: { color: 'rgba(255,255,255,0.08)' }, ticks: { color: '#CBD5E1' } } } }} />
          </CardContent>
        </Card>
      </Grid>
    </Grid>
  );
}

export default AnalyticsCharts;
